update club_governance_ban
set status = 'EXPIRED', version = version + 1,
    update_by = 'SYSTEM', update_time = #{now}
where club_id = #{clubId} and status = 'ACTIVE'
  and source_type = 'CLUB' and expires_at is not null and expires_at <= #{now}

update club_governance_ban
set status = 'EXPIRED', version = version + 1,
    update_by = 'SYSTEM', update_time = #{now}
where club_id = #{clubId} and target_member_id = #{targetMemberId}
  and status = 'ACTIVE' and source_type = 'CLUB'
  and expires_at is not null and expires_at <= #{now}

