delete from club_member
where club_id = #{clubId} and member_id = #{memberId}
  and status = 1 and del_flag = 0

mapper.select:
select 
from club_governance_case
where club_id = #{clubId} and filer_member_id = #{filerMemberId}
  and submit_request_id = #{requestId}
limit 1 for update

select 
from club_governance_case

    case_type = #{caseType}
    and status = #{status}
    and club_id = #{clubId}

order by case when status = 'PENDING' then 0 else 1 end, create_time asc, id asc

