update club_governance_ban
set status = 'UNBANNED', unbanned_by_member_id = null, unbanned_at = now(),
    unban_reason = #{reason}, unban_request_id = #{requestId},
    version = version + 1, update_by = 'PLATFORM', update_time = now()
where id = #{id} and club_id = #{clubId}
  and status = 'ACTIVE' and version = #{expectedVersion}
